## Concept 1 - a type whose values are classes

`test.extend<Pages>` needs a type describing what each fixture *hands you*. For page objects
that is an instance of the class:

```ts
type Pages = {
  loginPage: LoginPage;          // an instance
  dashboardPage: DashboardPage;
};
```

`LoginPage` used as a **type** means "an instance of LoginPage". The same name used as a
**value** - `new LoginPage(page)` - means the class itself. TypeScript keeps the two namespaces
separate, which is why one identifier can do both jobs.

class Cart {
  items: string[] = [];
}

// `Cart` as a type on the left, `Cart` as a value on the right.
const myCart: Cart = new Cart();
myCart.items.push("apple");

console.log(myCart.items, myCart instanceof Cart);

// Re-exporting is just handing the same value on under your own module's name.
const upstream = { expect: (v: unknown) => ({ toBe: (w: unknown) => v === w }) };
const mine = { expect: upstream.expect };      // same function, new home

console.log(mine.expect(2).toBe(2));
console.log(mine.expect === upstream.expect);  // true - not a copy

// The shape it returns: an object of the module's exports.
const mod = await import("node:path");

console.log(typeof mod.join, mod.join("a", "b"));

# Week 5, Day 4.2 - Composing page objects

Day 3's spec opened with three lines of `new`:

```ts
const loginPage = new LoginPage(page);
const dashboardPage = new DashboardPage(page);
const transferPage = new TransferPage(page);
```

Every test. Add a fourth page and you edit every test again. Today those disappear.

> **Mode: test-runner.** This part is about running specs with the Playwright test runner. The studio editor runs library code, so follow these along in your own checkout.

import { writeProjectFile } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/pages/TransferPage.ts", `// Week 5, Days 3-4 — the fund-transfer screen, reached from the Add Payee tile.
import { type Locator, type Page } from "@playwright/test";
import { BasePage } from "./BasePage";

export class TransferPage extends BasePage {
  readonly addPayeeButton: Locator;
  readonly amountBox: Locator;
  readonly sendButton: Locator;

  constructor(page: Page) {
    super(page);
    this.addPayeeButton = page.getByRole("button", { name: "ADD PAYEE" });
    this.amountBox = page.getByPlaceholder("Enter Amount");
    this.sendButton = page.getByRole("button", { name: "SEND" });
  }

  async openAddPayeeForm(): Promise<void> {
    await this.addPayeeButton.click();
  }
}
`);

import { writeProjectFile } from "../_shared/deno-helpers.ts";

// The one import every spec will use.

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/pages/test.ts", `// Week 5, Day 4 — the single import every spec uses.
//
// Each page object becomes a fixture, so a test asks for the pages it needs by
// name and never writes \`new LoginPage(page)\`. A test that doesn't ask for a page
// never pays to construct it.
import { test as base, expect } from "@playwright/test";
import { LoginPage } from "./LoginPage";
import { DashboardPage } from "./DashboardPage";
import { TransferPage } from "./TransferPage";

type Pages = {
  loginPage: LoginPage;
  dashboardPage: DashboardPage;
  transferPage: TransferPage;
};

export const test = base.extend<Pages>({
  loginPage: async ({ page }, use) => {
    await use(new LoginPage(page));
  },
  dashboardPage: async ({ page }, use) => {
    await use(new DashboardPage(page));
  },
  transferPage: async ({ page }, use) => {
    await use(new TransferPage(page));
  },
});

// Re-exported so a spec needs exactly one import line.
export { expect };
`);

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/day4-pom.spec.ts", `// Week 5, Day 4 — the Page Object Model, composed.
//
// Count the DOM details in this file: none. No placeholders, no button names, no
// CSS, no URLs. Every line describes what a person did or what should be true.
//
// Written by a cell in week5/day4_2.ipynb. Run it yourself:
//   npx playwright test week5/generated/day4-pom.spec.ts
import { test, expect } from "./pages/test";

test.describe("Page Object Model", () => {
  test("Step 1 — signing in lands on the dashboard", async ({ loginPage, dashboardPage }) => {
    await loginPage.goto("/");
    await loginPage.signIn();

    // The class got us here; the test decides what that means.
    await expect(dashboardPage.userName).toBeVisible();
    await expect(dashboardPage.accountBalance).toBeVisible();
  });

  test("Step 2 — the dashboard has twelve tiles", async ({ loginPage, dashboardPage }) => {
    await loginPage.goto("/");
    await loginPage.signIn();

    await expect(dashboardPage.tiles).toHaveCount(12);
  });

  test("Step 3 — a tile opens its own screen", async ({ loginPage, dashboardPage, page }) => {
    await loginPage.goto("/");
    await loginPage.signIn();
    await dashboardPage.openTile("Pay Bills");

    await expect(page).toHaveURL(/paymentDashboard/);
  });

  test("Step 4 — three pages in one journey", async ({ loginPage, dashboardPage, transferPage }) => {
    await loginPage.goto("/");
    await loginPage.signIn();
    await dashboardPage.openTile("Add Payee");

    // TransferPage takes over from here — the test never learns the URL changed.
    await expect(transferPage.addPayeeButton).toBeVisible();
    expect(transferPage.section()).toBe("transferDashboard");
  });

  test("Step 5 — a different user, through the same classes", async ({ loginPage, dashboardPage, page }) => {
    const { USERS } = await import("../../_shared/test-helpers");

    await loginPage.goto("/");
    await loginPage.signIn(USERS[1]);
    await expect(page).toHaveURL(/dashboard/);
    await expect(dashboardPage.logoutButton).toBeVisible();
  });

  test("Step 6 — a refused login, using the same class", async ({ loginPage, dashboardPage, page }) => {
    await loginPage.goto("/");
    await loginPage.signInExpectingRefusal("leela@gmail.com", "WrongPass1");

    // One class serves both outcomes because it asserts neither.
    await expect(page).not.toHaveURL(/dashboard/);
    await expect(dashboardPage.userName).toHaveCount(0);
  });
});
`);

// Expected: 6 passed.
await runSpec("week5/generated/day4-pom.spec.ts");

## Step 5 - three pages in one journey

Step 4 of the spec signs in, opens a tile, and asserts on the transfer screen. The test never
learns that the URL changed:

```ts
await loginPage.goto("/");
await loginPage.signIn();
await dashboardPage.openTile("Add Payee");
await expect(transferPage.addPayeeButton).toBeVisible();
expect(transferPage.section()).toBe("transferDashboard");
```

`section()` comes from `BasePage`, so all three classes have it for free.

## Worker fixtures, for things that are expensive once

A normal fixture runs per test. A **worker** fixture runs once per worker process:

```ts
export const test = base.extend<{}, { apiToken: string }>({
  apiToken: [async ({}, use) => {
    const token = await fetchToken();     // once per worker, not per test
    await use(token);
  }, { scope: "worker" }],
});
```

Two type parameters: test-scoped fixtures first, worker-scoped second.

| Scope | Runs | Good for |
|---|---|---|
| `test` (default) | once per test | page objects, per-test data |
| `worker` | once per worker process | an auth token, a seeded database |

The catch: worker fixtures are **shared** between the tests in that worker. Anything mutable in
there is a channel for tests to interfere with each other - which is the same trap as the shared
account in [day2_2](/learn/w5/d2/p2).

// Why worker scope is not free. Two counters, same idea as Playwright's two scopes.
let workerBuilds = 0;
let testBuilds = 0;

const workerScoped = { token: "T-" + ++workerBuilds };   // built once, reused

function testScopedFixture() {
  testBuilds++;
  return { cart: [] as string[] };                        // fresh per test
}

const testA = testScopedFixture();
const testB = testScopedFixture();
testA.cart.push("item from test A");

console.log("worker fixture built:", workerBuilds, "time(s), token:", workerScoped.token);
console.log("test fixture built:  ", testBuilds, "time(s)");
console.log("test B's cart:", testB.cart, "<- unaffected by test A");
console.log("both tests share:", workerScoped.token, "<- mutate this and they interfere");

## Automatic fixtures

`{ auto: true }` runs a fixture even when no test asks for it. Useful for cross-cutting setup
(attaching a logger, failing a test on a console error) and dangerous everywhere else, because it
is invisible at the call site:

```ts
failOnConsoleError: [async ({ page }, use) => {
  const errors: string[] = [];
  page.on("console", m => { if (m.type() === "error") errors.push(m.text()); });
  await use();
  expect(errors, "console errors").toEqual([]);
}, { auto: true }],
```
